-- Coordinated cutover: stop app and worker before expanding StoreState.
-- Materialize the approved profile grants and existing patient ids without
-- changing any clinical eligibility, department, service or patient scope.
CREATE OR REPLACE FUNCTION cvg_runtime_entity_collections() RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  SELECT ARRAY['users','sessions','patients','encounters','admissions','services','reasonCodes',
    'requests','items','samples','procedures','schedules','results','resultVersions',
    'notifications','idempotency','attachments','departments','accessGroups','patientGrants']::text[]
$$;
CREATE UNIQUE INDEX cvg_access_groups_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection = 'accessGroups';
CREATE UNIQUE INDEX cvg_patient_grants_target_unique ON cvg_runtime_entities ((data->>'userId'), (data->>'patientId')) WHERE collection = 'patientGrants';
DO $$
DECLARE
  current_version bigint;
  approved jsonb := '{"ADMIN":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage"],"MANAGER":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.update","department.members.manage","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","service.catalog.manage","sla_policy.manage","reason_code.manage","user_role.manage","audit.view"],"VETERINARIAN":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"INPATIENT_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","patient.create","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","result.review","attachment.download","notification.acknowledge"],"LAB_TECH":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge","item.reject"],"RADIOLOGY_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"ULTRASOUND_TEAM":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"VIEWER":["department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect"],"SUPERADMIN":["access_group.view","access_group.create","access_group.update","access_group.deactivate","access_group.assign","patient_scope.manage","user.view","user.create","user.update","user.deactivate","service.catalog.create","service.catalog.update","service.catalog.deactivate","department.view","department.create","department.update","department.deactivate","department.members.manage","service.catalog.view","realtime.connect","service.catalog.manage","sla_policy.manage","critical_result_policy.manage","reason_code.manage","user_role.manage","patient.data_export","audit.view","health.liveness","health.readiness","outbox.manage","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","admission.context.manage","encounter.manage","request.create","request.cancel","request.duplicate_override","item.cancel","item.reject","item.complete","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","result.review","attachment.download","notification.acknowledge","attachment.upload_session","attachment.finalize","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","sample.receive","sample.process","sample.recollection.request","sample.replacement.receive","patient.create"]}'::jsonb;
  timestamp_text text := to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  user_count integer;
  grant_count integer;
BEGIN
  SELECT version INTO current_version FROM cvg_runtime_state WHERE id = 1 FOR UPDATE;
  IF current_version IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM cvg_runtime_entities WHERE collection = 'users' AND NOT (approved ? (data->>'role'))) THEN
      RAISE EXCEPTION 'ACCESS_GROUP_MIGRATION_UNKNOWN_PROFILE';
    END IF;
    INSERT INTO cvg_runtime_entities(collection, entity_key, position, data, written_version)
    SELECT 'accessGroups', 'access-group-' || lower(role), row_number() OVER (ORDER BY role),
      jsonb_build_object('id','access-group-' || lower(role),'code','PROFILE_' || role,'description','Perfil inicial ' || role,
        'active',true,'permissions',permissions,'systemRole',role,'version',1,'createdAt',timestamp_text,'updatedAt',timestamp_text),
      current_version + 1 FROM jsonb_each(approved) AS group_grants(role, permissions);
    UPDATE cvg_runtime_entities SET data = data || jsonb_build_object('accessGroupId','access-group-' || lower(data->>'role'),
      'version', (data->>'version')::integer + 1), written_version = current_version + 1 WHERE collection = 'users';
    GET DIAGNOSTICS user_count = ROW_COUNT;
    WITH targets AS (
      SELECT DISTINCT data->>'id' AS user_id, jsonb_array_elements_text(COALESCE(data->'patientIds', '[]'::jsonb)) AS patient_id
      FROM cvg_runtime_entities WHERE collection = 'users'
    ), grants AS (
      SELECT *, 'patient-grant-' || md5(jsonb_build_array(user_id,patient_id)::text) AS grant_id FROM targets
    )
    INSERT INTO cvg_runtime_entities(collection, entity_key, position, data, written_version)
    SELECT 'patientGrants',grant_id,row_number() OVER (ORDER BY user_id,patient_id),
      jsonb_build_object('id',grant_id,'userId',user_id,'patientId',patient_id,'active',true,'source','LEGACY',
        'version',1,'createdAt',timestamp_text,'updatedAt',timestamp_text),current_version + 1 FROM grants;
    GET DIAGNOSTICS grant_count = ROW_COUNT;
    UPDATE cvg_runtime_state SET state = cvg_runtime_state_header(state), version = current_version + 1, updated_at = now() WHERE id = 1;
    INSERT INTO audit_events(id,event_type,entity_type,entity_id,correlation_id,metadata,occurred_at)
    VALUES ('audit-migration-020','HospitalAccessGroupsMigrated','SchemaMigration','020_hospital_access_groups','corr-migration-020',
      jsonb_build_object('userCount',user_count,'legacyPatientGrantCount',grant_count,'clinicalScopeChanged',false),CURRENT_TIMESTAMP);
  END IF;
END $$;
ALTER TABLE cvg_runtime_state ADD CONSTRAINT runtime_hospital_access_is_external
  CHECK (COALESCE(state->'accessGroups' = '[]'::jsonb AND state->'patientGrants' = '[]'::jsonb, false));
UPDATE relational_schema_markers SET schema_version = '020_hospital_access_groups' WHERE marker_key = 'RELATIONAL_CLINICAL_CORE_EXPAND_V1';
